starter.css:
body { background: #ffffff; }
.pass { display: grid; gap: 8px; justify-items: start; max-width: 340px; }
.pass h2 { margin: 0; }
.pass p { margin: 0; }
.price { color: #9a9a9a; }
.note a { color: #1b1830; text-decoration: none; font-weight: 600; }
input { font: inherit; padding: 6px 8px; border: 1px solid #dddddd; border-radius: 6px; background: #ffffff; }
.btn { font: inherit; padding: 8px 16px; border: 0; border-radius: 8px; background: #f4a261; color: #ffffff; }

